function single_element(comboQueries, operation, form, queryString_element, queryString_next, return_value, callback, last) {

  let client;
  if (comboQueries && comboQueries.length) {
    query = comboQueries.pop();
    if (form.map(function (e) { return e.name; }).includes(query.name)) {
      pool.connect().then(c => {
        client = c;
        return client.query(query.queryString);
      }).then(res => {
        client.release();
        var position = form.map(function (e) { return e.name; }).indexOf(query.name); // find combobox position by name
        form[position]['options'] = res.rows;
        single_element(comboQueries, operation, form, queryString_element, queryString_next, return_value, callback, last);  // recursively unroll the combobox queries array
      }).catch(error => {
        return_value.response = {
          "isBase64Encoded": false,
          "statusCode": 500,
          "body": JSON.stringify(error)
        };
        return_value.status = error;
        callback(return_value);
      });
    } else {  // go on
      single_element(comboQueries, operation, form, queryString_element, queryString_next, return_value, callback, last);
    }
  } else {
    last(operation, form, queryString_element, queryString_next, return_value, callback);
  }
};

function queryListWithConditions(keys, queryString, conditions) {

    for (var key in keys) { // add all the WHERE conditions
        // if no WHERE clause, add it, otherwise use AND
        var clause = queryString.indexOf('WHERE') <= -1 ? " WHERE " : " AND ";
        if (conditions[key]) { // condition already provided with form, insert it
            if (conditions[key].test && conditions[key].test !== keys[key]) break; // move forward if test provided and not met
            var cond = conditions[key].condition.replace('$param', keys[key]); // condition must use $param as parameter if needed
            queryString = queryString.slice(0,queryString.length - 1) + clause + cond + ';';
        } else if (keys[key].id) { // found search parameter, insert "name=value"
            queryString = queryString.slice(0,queryString.length - 1) + clause + key + "=" + '\'' + keys[key].id +'\';';
        } else if (keys[key].value) { // found subtable parameter, insert "key_son=value_parent"
            queryString = queryString.slice(0,queryString.length - 1) + clause + keys[key].son + "=" + '\'' + keys[key].value +'\';';
        } else if (keys[key]!="") {
          queryString = queryString.slice(0,queryString.length - 1) + clause + key + "=" + '\'' + keys[key] +'\';';
        }// else skip this element
    }

    return queryString;
}

function replacekeys(queryString, keys) {
    if (queryString) {
        for (var key in keys) {
            let toReplace = '$' + key + '$';
            let replacement = keys[key].value ? keys[key].value : keys[key]; // handle subtables
            let newString = queryString.replace(toReplace, replacement);
            while (newString !== queryString) { // handle multiple occurences
                queryString = newString;
                newString = queryString.replace(toReplace, replacement);
            }
        }
    }
    return queryString;
}

module.exports = {
  process_request: function (event, context, form, queries, callback) {

    context.callbackWaitsForEmptyEventLoop = false; // don't know why, but this prevents the lambda to hang

    var return_value = {};

    return_value.response = {
      "isBase64Encoded": false,
      "statusCode": 500,
      "body": "Generic Error"
    };

    return_value.status = "ERROR";

    return_value.query = '';

    var operation = event.queryStringParameters.operation;

    var conditions = queries.conditions ? queries.conditions : {};

    var keys = JSON.parse(event.queryStringParameters.keys);

    var queryString = replacekeys(queries.list, keys);

    queryString = operation === 'sublist' ? queryListWithConditions(keys, queryString, conditions.sub_table) : queryListWithConditions(keys, queryString, conditions.table);

    var queryString_element = replacekeys(queries.element, keys);

    var queryString_next = replacekeys(queries.next, keys);

    var deleteString = replacekeys(queries.delete, keys);

    for (var i = 0; i < queries.combo.length; i++) {
        queries.combo[i].queryString = replacekeys( queries.combo[i].queryString, keys);
    }

    var comboQueries = queries.combo;

    var actualForm = (operation === 'search') ? form.search_form : form.element_form;

    if (event.httpMethod === "POST") {
      // POST triggers either record update or search list with filled form conditions
      var body = JSON.parse(event.body.toString());
      var updateSearchString = (operation === 'search') ? 
          queryListWithConditions(body, queryString, conditions.search) : 
          replacekeys(queries.update, body);

      let client;
      pool.connect().then(c => {
        client = c;
        return client.query(updateSearchString);
      }).then(res => {
        client.release();
        return_value.query = updateSearchString;
        return_value.response = {
          "statusCode": 200,
          "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
          "isBase64Encoded": false,
          "body": JSON.stringify(res.rows)
        };
        return_value.status = "Update/Search OK";
        callback(return_value);
      }).catch(error => {
        return_value.query = updateSearchString;
        return_value.response = {
          "isBase64Encoded": false,
          "statusCode": 500,
          "body": JSON.stringify(error)
        };
        return_value.status = error;
        callback(return_value);
      });
    }

    if (event.httpMethod === "DELETE") {

      let client;
      pool.connect().then(c => {
        client = c;
        return client.query(deleteString);
      }).then(res => {
        client.release();
        return_value.query = deleteString;
        return_value.response = {
          "statusCode": 200,
          "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
          "isBase64Encoded": false,
          "body": JSON.stringify(res.rows)
        };
        return_value.status = "Update OK";
        callback(return_value);
      }).catch(error => {
        return_value.query = deleteString;
        return_value.response = {
          "isBase64Encoded": false,
          "statusCode": 500,
          "body": JSON.stringify(error)
        };
        return_value.status = error;
        callback(return_value);
      });
    }

    if (event.httpMethod === "PUT") {
      var body = JSON.parse(event.body.toString());
      var insertNewString = replacekeys(queries.new, body);
      let client;
      pool.connect().then(c => {
        client = c;
        return client.query(insertNewString);
      }).then(res => {
        client.release();
        return_value.query = insertNewString;
        return_value.response = {
          "statusCode": 200,
          "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
          "isBase64Encoded": false,
          "body": JSON.stringify(res.rows)
        };
        return_value.status = "Insert OK";
        callback(return_value);
      }).catch(error => {
        return_value.query = insertNewString;
        return_value.response = {
          "isBase64Encoded": false,
          "statusCode": 500,
          "body": JSON.stringify(error)
        };
        return_value.status = error;
        callback(return_value);
      });
    }

    if (event.httpMethod === "GET") {
      let client;
      if (operation === 'list' || operation === 'sublist') { // query the full table 
        pool.connect().then(c => {
          client = c;
          return client.query(queryString);
        }).then(res => {
          client.release();
          return_value.query = queryString;
          return_value.response = {
            "statusCode": 200,
            "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
            "body": JSON.stringify(res.rows),
            "isBase64Encoded": false
          };
          return_value.status = "GET List/SubList OK";
          callback(return_value);
        }).catch(error => {
          return_value.query = queryString;
          return_value.response = {
            "isBase64Encoded": false,
            "statusCode": 500,
            "body": JSON.stringify(error)
          };
          return_value.status = error;
          callback(return_value);
        });
      } else if (operation === 'subkeys') { // return the sublist conditions
        return_value.response = {
            "statusCode": 200,
            "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
            "body": JSON.stringify(form.subtable_form),
            "isBase64Encoded": false
          };
          return_value.status = "GET Subtable Form OK";
          callback(return_value);
      } else if (operation === 'keys') {
        return_value.response = {
            "statusCode": 200,
            "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
            "body": JSON.stringify(form.table_form),
            "isBase64Encoded": false
          };
          return_value.status = "GET Table Keys OK";
          callback(return_value);
      } else {    //query one element or NEW element
        single_element(comboQueries, operation, actualForm, queryString_element, queryString_next, return_value, callback,
          (operation, form, queryString_element, queryString_next, return_value, callback) => {
            // LAST FUNCTION OF single_element -- BEGIN
            let client;
            if (operation === 'select') { //query one element  
              pool.connect().then(c => {
                client = c;
                return client.query(queryString_element);
              }).then(res => {
                client.release();
                return_value.query = queryString_element;
                var jsonString = res.rows[0];
                for (var i = 0; i < form.length; i++) {
                  var element = form[i];
                  if (jsonString[element.name]) {
                    form[i]['value'] = jsonString[element.name];
                  }
                }
                var jsonObj = JSON.stringify(form);
                return_value.response = {
                  "statusCode": 200,
                  "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
                  "body": jsonObj,
                  "isBase64Encoded": false
                };
                return_value.status = "GET element OK";
                callback(return_value);
              }).catch(error => {
                return_value.query = queryString_element;
                return_value.response = {
                  "isBase64Encoded": false,
                  "statusCode": 500,
                  "body": JSON.stringify(error)
                };
                return_value.status = error;
                callback(return_value);
              });
            } else if (operation === 'search') {
              return_value.response = {
                "statusCode": 200,
                "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
                "isBase64Encoded": false,
                "body": JSON.stringify(form)
              };
              return_value.status = "GET search form OK";
              callback(return_value);
            } else if (operation === 'create') {  //  NEW element
              if (queryString_next) {
                pool.connect().then(c => {
                  client = c;
                  return client.query(queryString_next);
                }).then(res => {
                  client.release();
                  return_value.query = queryString_next;
                  var jsonString = res.rows[0];
                  for (var i = 0; i < form.length; i++) {
                    var element = form[i];
                    if (jsonString[element.name]) {
                      form[i]['value'] = jsonString[element.name];
                    } else if (keys[element.name]) { // add primary keys values to the form
                        form[i]['value'] = keys[element.name];
                    }
                  }
                  var jsonObj = JSON.stringify(form);
                  return_value.response = {
                    "statusCode": 200,
                    "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
                    "body": jsonObj,
                    "isBase64Encoded": false
                  };
                  return_value.status = "GET new element OK";
                  callback(return_value);
                }).catch(error => {
                  return_value.query = queryString_next;
                  return_value.response = {
                    "isBase64Encoded": false,
                    "statusCode": 500,
                    "body": JSON.stringify(error)
                  };
                  return_value.status = error;
                  callback(return_value);
                });
              } else { // empty form 
                var jsonObj = JSON.stringify(form);
                return_value.response = {
                  "statusCode": 200,
                  "headers": { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
                  "body": jsonObj,
                  "isBase64Encoded": false
                };
                return_value.status = "GET new element OK";
                callback(return_value);
              }
            }
          });
        // LAST FUNCTION OF single_element -- END
      }
    }
  }
}
